    "MASTERED PLAYMAKER ROUTE":{"ms":"LALUAN PLAYMAKER MAHIR","ja":"熟練の創造ルート"},
    "MATCH MADE IN HEAVEN":{"ms":"PADANAN SEMPURNA","ja":"運命のペア"},
    "MAX PLAYERS PER TEAM":{"ms":"MAKSIMUM PEMAIN SETIAP PASUKAN","ja":"各チームの最大人数"},
    "MEET THE DEVELOPERS ↗":{"ms":"KENALI PEMBANGUN ↗","ja":"開発者について ↗"},
